window.VERIFICA_MODULOS = {
  "LOG.01": {"f": "erro", "p": "Os passos abaixo deveriam ensinar um robô a pedir comida no app. Um deles não serve para um algoritmo. Toque nele.", "t": ["Abrir o app e tocar na busca.", "Digitar “pizza” e tocar no primeiro resultado.", "Escolher um restaurante bom.", "Tocar em “Finalizar pedido” e pagar com o cartão salvo."], "e": 2, "por": "“Bom” depende de quem decide: duas pessoas escolheriam diferente, e o computador não tem bom senso. Um passo de algoritmo diz exatamente o que fazer, como “o de maior nota com entrega abaixo de 40 minutos”."},
  "PY.01": {"f": "lacunas", "p": "Complete: o que o recuo faz em Python.", "t": "Depois de if nota >= 70:, as linhas com {{recuo}} de 4 espaços formam o {{bloco}} do if e só rodam quando a condição é verdadeira. A primeira linha sem recuo já está {{fora}} do if e roda sempre.", "x": ["enfeite", "comentário", "dentro"], "por": "Em Python o recuo não é estética: é ele que diz o que pertence ao bloco. Mudar o recuo muda o que roda."},
  "LOG.02": {"f": "escolha", "p": "x vale 5 e o programa executa x = x + 2. O que acontece?", "o": [["O Python calcula 5 + 2 e o nome x passa a apontar para 7; o 5 deixa de estar em x.", true, "O = manda guardar: calcula a direita e guarda na esquerda. A variável aponta para um valor por vez."], ["Dá erro, porque x não pode ser igual a x + 2.", false, "Isso seria ler o = como equação da matemática. Em programação ele quer dizer “recebe”, e a linha é válida."], ["x passa a guardar os dois valores, 5 e 7.", false, "Uma variável guarda um valor por vez. Quando recebe o 7, o 5 sai dela."]]},
  "LOG.03": {"f": "ordem", "p": "Ponha na ordem o que o Python faz em 2 + 3 * 4 == 14.", "t": ["Multiplica primeiro: 3 * 4 dá 12", "Soma: 2 + 12 dá 14", "Compara com ==: 14 == 14 dá True"], "por": "A multiplicação vem antes da soma, e a comparação vem depois das contas. Com um = só, a linha nem compararia: daria erro."},
  "LOG.04": {"f": "escolha", "p": "Qual é a negação de “tem 18 anos e tem CNH”?", "o": [["Não tem 18 anos ou não tem CNH.", true, "Lei de De Morgan: negar um “e” vira um “ou” com as duas partes negadas. Basta faltar uma das duas condições."], ["Não tem 18 anos e não tem CNH.", false, "Essa frase é mais forte do que a negação: quem tem 18 anos mas não tem CNH também não cumpre a regra, e ficaria de fora."], ["Tem 18 anos ou tem CNH.", false, "Isso troca o conectivo mas não nega as partes. A negação troca o e pelo ou e nega cada parte."]]},
  "LOG.05": {"f": "erro", "p": "A nota é 85 e o programa tem if nota >= 70: … elif nota >= 80: … else: …. Uma frase está errada. Toque nela.", "t": ["O Python testa a primeira condição: 85 >= 70 dá True.", "Ele executa o bloco do if.", "Depois ele testa o elif, que também é verdadeiro, e executa esse bloco também.", "O else não roda, porque uma condição já foi verdadeira."], "e": 2, "por": "No if/elif, o Python para na primeira condição verdadeira e pula o resto. Por isso, nas faixas, a condição mais restrita (>= 80) vem antes."},
  "LOG.06": {"f": "lacunas", "p": "Complete: por que este laço nunca para?", "t": "Em i = 0 e while i < 10: print(i), o valor de i nunca {{muda}}, então a condição continua {{verdadeira}} para sempre. Falta, dentro do laço, a linha i = i + 1, que faz a condição ficar {{falsa}} um dia.", "x": ["para", "falsa no começo", "maior"], "por": "Um while só termina quando a condição fica falsa. Se nada dentro do laço muda a variável da condição, ele roda para sempre."},
  "LOG.09": {"f": "ordem", "p": "O programa parou com uma mensagem de erro. Ponha na ordem o jeito certo de investigar.", "t": ["Ler o tipo do erro e o número da linha na mensagem", "Ir até essa linha e olhar os valores que ela usa", "Imprimir os valores suspeitos para conferir o que chega ali", "Corrigir uma coisa e rodar de novo"], "por": "A mensagem já diz o tipo e a linha: é por ela que se começa. Mudar o código no chute, várias coisas de uma vez, esconde a causa."},
  "LOG.07": {"f": "escolha", "p": "A função def dobro(x): print(x * 2) é usada em total = dobro(5) + 1. O que acontece?", "o": [["Aparece 10 na tela, mas dobro(5) devolve None, e None + 1 dá erro: faltou return x * 2.", true, "print mostra na tela; return devolve o valor para quem chamou. Sem return, a função devolve None."], ["total fica 11, porque o print devolve o 10.", false, "O print só mostra o valor; ele não devolve nada para a conta. Quem devolve é o return."], ["total fica 10, porque o + 1 é ignorado.", false, "O + 1 não é ignorado: a conta tenta somar o que a função devolveu, que é None, e para com erro."]]},
  "LOG.08": {"f": "ordem", "p": "Você precisa de um programa que lê as notas, calcula a média de cada aluno e lista os aprovados. Ponha na ordem a forma de construir.", "t": ["Escrever e testar a média de um aluno só, com números fixos", "Transformar essa conta numa função", "Aplicar a função a todos os alunos da lista", "Filtrar e mostrar os aprovados"], "por": "Decompor é resolver e testar a menor parte primeiro e só depois juntar. Escrever tudo num bloco só deixa o erro sem endereço."},
  "PY.02": {"f": "escolha", "p": "total = 10. Qual linha mostra Total: 10 sem dar erro?", "o": [["print(f\"Total: {total}\")", true, "A f-string põe o valor dentro do texto e converte sozinha. Também funcionaria \"Total: \" + str(total)."], ["print(\"Total: \" + total)", false, "Texto só se junta com texto: \"Total: \" + 10 para com TypeError."], ["print(\"Total: \" + \"total\")", false, "Assim aparece a palavra total, não o valor 10: as aspas transformam o nome em texto."]]},
  "PY.03": {"f": "lacunas", "p": "Complete: índices de uma lista.", "t": "Em musicas = [\"a\", \"b\", \"c\"], o primeiro item é musicas[{{0}}] e o último é musicas[2] ou musicas[{{-1}}]. Pedir musicas[3] dá {{IndexError}}, porque a lista tem 3 itens e os índices vão de 0 a 2.", "x": ["1", "3", "None"], "por": "O índice começa em 0, então o último de uma lista de 3 itens é o 2. O índice negativo conta do fim: -1 é o último."},
  "PY.04": {"f": "erro", "p": "precos = {\"cafe\": 5, \"pao\": 1}. Uma frase está errada. Toque nela.", "t": ["precos[\"cafe\"] devolve 5: procura-se pela chave.", "precos.get(\"bolo\", 0) devolve 0 em vez de dar erro.", "precos[5] devolve \"cafe\": dá para procurar pelo valor do mesmo jeito.", "for nome, preco in precos.items() percorre cada par chave e valor."], "e": 2, "por": "O dicionário procura pela chave, não pelo valor: precos[5] dá KeyError. Para achar a chave de um valor, é preciso percorrer os itens."},
  "PY.05": {"f": "escolha", "p": "a = [1, 2]; b = a; b.append(3). Quanto vale a?", "o": [["[1, 2, 3], porque b = a não copia: a e b são dois nomes para a mesma lista.", true, "b = a cria um apelido. Para copiar, use b = a.copy() ou b = list(a)."], ["[1, 2], porque b é uma cópia de a.", false, "b = a não cria cópia nenhuma: os dois nomes apontam para o mesmo objeto, então o append aparece nos dois."], ["Dá erro, porque duas variáveis não podem guardar a mesma lista.", false, "Pode, e é comum: vários nomes podem apontar para o mesmo objeto. É isso que causa a surpresa."]]},
  "PY.06": {"f": "lacunas", "p": "Complete: o perigo de uma lista como valor padrão.", "t": "Em def adiciona(item, lista=[]):, a lista padrão é criada {{uma vez}}, quando a função é definida. Por isso cada chamada sem lista {{acumula}} os itens das anteriores. O jeito certo é usar lista={{None}} e criar a lista nova dentro da função.", "x": ["a cada chamada", "apaga", "[]"], "por": "O valor padrão é avaliado uma vez só. Com lista mutável, ele vira memória compartilhada entre as chamadas."},
  "PY.08": {"f": "escolha", "p": "Qual tratamento de erro é o melhor ao converter a idade digitada?", "o": [["try: idade = int(texto) / except ValueError: pedir de novo, avisando que só vale número.", true, "Pegar só o erro esperado (ValueError) e dizer o que fazer. Os outros erros continuam aparecendo."], ["try: idade = int(texto) / except: pass", false, "Um except genérico com pass engole todos os erros, inclusive os bugs do seu código, e o programa segue com dado errado."], ["Não tratar nada: se der erro, o usuário que digite certo.", false, "Entrada de usuário falha com frequência; o programa deve validar e explicar, não quebrar."]]},
  "PY.09": {"f": "erro", "p": "Você vai ler alunos.csv, que tem nomes com acento. Uma frase está errada. Toque nela.", "t": ["with open(\"alunos.csv\", encoding=\"utf-8\") as f: fecha o arquivo sozinho no fim do bloco.", "Sem encoding, o Python usa o padrão do sistema, e os acentos podem sair quebrados.", "O modo \"w\" abre o arquivo para leitura sem mexer no conteúdo.", "for linha in f: lê o arquivo uma linha por vez."], "e": 2, "por": "O modo \"w\" é de escrita e apaga o conteúdo ao abrir. Para ler, use \"r\" (o padrão)."},
  "PY.10": {"f": "escolha", "p": "Você criou random.py na pasta do projeto e agora import random não acha random.randint. Por quê?", "o": [["O Python importou o seu random.py, que está na pasta do projeto, no lugar do módulo original.", true, "A pasta do script vem primeiro na busca do import. Nunca dê ao seu arquivo o nome de um módulo que você usa."], ["O módulo random foi removido do Python.", false, "random faz parte da biblioteca padrão; o problema é o nome do seu arquivo."], ["Faltou instalar o random com pip.", false, "Módulos da biblioteca padrão já vêm com o Python. O conflito é de nome."]]},
  "PY.13": {"f": "ordem", "p": "A função media(lista) devolve a média. Ponha os testes na ordem do mais comum para o mais raro, como numa boa bateria de testes.", "t": ["Caso normal: media([6, 8]) deve dar 7", "Borda: media([5]) deve dar 5", "Borda: media([]) deve dar um erro claro", "Erro: media([\"a\"]) deve recusar texto"], "por": "Testar só o caso feliz deixa os bugs nas bordas: lista vazia, um item só, tipo errado. A bateria cobre o normal e as bordas."},
  "PY.07": {"f": "escolha", "p": "Qual compreensão faz o mesmo que o laço: aprovados = [] / for n in notas: if n >= 70: aprovados.append(n)?", "o": [["aprovados = [n for n in notas if n >= 70]", true, "A compreensão lê: o que entra (n), de onde vem (for n in notas) e o filtro (if n >= 70)."], ["aprovados = [n >= 70 for n in notas]", false, "Isso gera uma lista de True e False, não as notas aprovadas."], ["aprovados = [for n in notas if n >= 70]", false, "Falta dizer o que entra na lista antes do for: é inválido."]]},
  "PY.11": {"f": "lacunas", "p": "Complete: classe e objeto.", "t": "class Pedido: é o {{molde}}; ele sozinho não cria nada. p = Pedido(\"pizza\") cria um {{objeto}}, o pedido de verdade. Dentro dos métodos, o primeiro parâmetro, {{self}}, é o próprio objeto que está sendo usado.", "x": ["pedido", "método", "this"], "por": "A classe descreve; o objeto existe. Esquecer o self nos métodos dá erro de argumentos."},
  "PY.14": {"f": "erro", "p": "Você quer extrair CEPs (como 79070-900) de um texto. Uma frase está errada. Toque nela.", "t": ["O padrão \\d{5}-\\d{3} pede 5 dígitos, um hífen e 3 dígitos.", "re.findall(r\"\\d{5}-\\d{3}\", texto) devolve todos os CEPs encontrados.", "O padrão .* também serve, porque pega qualquer CEP.", "Vale testar com textos que não deveriam casar, como um telefone."], "e": 2, "por": ".* pega qualquer coisa, inclusive o que não é CEP: amplo demais. Padrão bom casa com o que deve e recusa o resto."},
  "PY.12": {"f": "escolha", "p": "def media(notas: list[float]) -> float: recebe media(\"abc\"). O que acontece?", "o": [["O Python roda normalmente até o erro aparecer na conta; quem avisaria antes é uma ferramenta como o mypy.", true, "Anotação de tipo é documentação conferida por ferramentas, não pelo Python na hora de rodar."], ["O Python recusa a chamada na hora, por causa da anotação.", false, "O Python ignora as anotações ao executar; elas não viram verificação automática."], ["A anotação converte \"abc\" em lista de float.", false, "Anotação não converte nada; só descreve o que se espera."]]},
  "BD.01": {"f": "escolha", "p": "O que um SGBD faz que uma planilha grande não faz?", "o": [["Garante regras sobre os dados (tipos, chaves, ligações) e deixa várias pessoas e programas usarem os mesmos dados ao mesmo tempo, sem estragá-los.", true, "O banco não é só um lugar para guardar: ele protege a integridade, controla o acesso e separa os dados dos programas que os usam."], ["Guarda mais linhas, e só isso.", false, "Tamanho não é a diferença principal: uma planilha bem pequena também perde integridade quando duas pessoas a editam."], ["Deixa os dados mais bonitos de ver.", false, "Aparência é coisa da ferramenta de visualização. O SGBD cuida de regras, acesso e consistência."]]},
  "BD.02": {"f": "lacunas", "p": "Complete: por que respostas guarda aluno_id, e não o nome do aluno.", "t": "Na tabela respostas, a coluna aluno_id é uma chave {{estrangeira}}: ela aponta para a chave {{primária}} de alunos. Assim o nome fica guardado uma vez só, e mudar o nome de um aluno não deixa respostas {{desencontradas}}.", "x": ["candidata", "repetidas", "secundária"], "por": "Guardar o id e não o nome evita repetir o mesmo dado em centenas de linhas, que um dia se desencontram."},
  "BD.03": {"f": "escolha", "p": "Você quer só o nome e o e-mail dos alunos. Qual consulta é a melhor?", "o": [["SELECT nome, email FROM alunos;", true, "Traz só as colunas que você quer: o resultado fica claro e leve."], ["SELECT * FROM alunos;", false, "O * traz todas as colunas, inclusive as que você não pediu, e esconde o que interessa."], ["SELECT alunos FROM nome, email;", false, "A ordem está trocada: depois do SELECT vêm as colunas, e depois do FROM vem a tabela."]]},
  "BD.04": {"f": "erro", "p": "Você quer as respostas em que o aluno marcou a letra C. Uma frase está errada. Toque nela.", "t": ["WHERE resposta = 'C' compara a coluna com o texto C.", "WHERE resposta = \"C\" faz o mesmo no PostgreSQL, porque aspas duplas e simples são iguais.", "WHERE resposta IN ('C', 'D') aceita C ou D.", "Texto no SQL vai entre aspas simples."], "e": 1, "por": "No PostgreSQL, aspas duplas indicam nome de coluna: \"C\" procura uma coluna chamada C e dá erro. Texto é sempre entre aspas simples: 'C'."},
  "BD.05": {"f": "escolha", "p": "Na tabela respostas, acertou é NULL quando o aluno deixou em branco. Qual filtro acha essas linhas?", "o": [["WHERE acertou IS NULL", true, "NULL quer dizer “não informado”, e nada é igual a ele: só IS NULL o encontra."], ["WHERE acertou = NULL", false, "Comparar com = NULL dá desconhecido, nunca verdadeiro: a consulta volta vazia."], ["WHERE acertou = 0", false, "Zero é “errou”, um valor informado. NULL é ausência de valor, outra coisa."]]},
  "BD.06": {"f": "lacunas", "p": "Complete: a ordem do resultado.", "t": "Sem {{ORDER BY}}, o banco devolve as linhas na ordem que for mais cômoda para ele, e essa ordem pode {{mudar}} de uma execução para outra. Para listar as questões da mais difícil para a mais fácil: ORDER BY nivel {{DESC}}.", "x": ["GROUP BY", "ASC", "nunca muda"], "por": "A ordem só é garantida com ORDER BY. DESC vai do maior para o menor; ASC, o padrão, do menor para o maior."},
  "BD.11": {"f": "escolha", "p": "respondida_em está guardada como texto, em formatos misturados (10/04/2026 e 2026-04-10). O que fazer antes de comparar datas?", "o": [["Padronizar tudo para AAAA-MM-DD (ou converter para o tipo data) e só então comparar.", true, "No formato AAAA-MM-DD, a ordem do texto coincide com a ordem do tempo; com formatos misturados, a comparação dá resultado errado sem avisar."], ["Comparar direto: o banco entende os dois formatos.", false, "Como texto, '10/04/2026' e '2026-04-10' são comparados letra por letra, e a ordem sai errada."], ["Apagar as linhas no formato brasileiro.", false, "Apagar perde dados; o certo é converter para um formato único."]]},
  "BD.07": {"f": "erro", "p": "Uma frase sobre esta consulta está errada. Toque nela: SELECT materia_id, nivel, COUNT(*) FROM questoes GROUP BY materia_id;", "t": ["GROUP BY materia_id forma um grupo por matéria.", "COUNT(*) conta as questões de cada grupo.", "nivel pode ficar no SELECT, porque o banco escolhe um nível por matéria.", "Para filtrar grupos depois de contar, usa-se HAVING."], "e": 2, "por": "Cada matéria tem vários níveis; o banco não sabe qual mostrar. Toda coluna do SELECT precisa estar no GROUP BY ou dentro de uma agregação."},
  "BD.08": {"f": "escolha", "p": "SELECT * FROM respostas, alunos; sem nenhuma condição ligando as duas tabelas. O que acontece?", "o": [["Cada resposta é combinada com todos os alunos: o produto cartesiano, com (linhas de respostas) × (linhas de alunos) linhas.", true, "O que liga cada resposta ao seu aluno é a condição: JOIN alunos ON respostas.aluno_id = alunos.id."], ["O banco liga sozinho pelas colunas de nome parecido.", false, "O banco não adivinha a ligação: sem condição, combina tudo com tudo."], ["Volta só a primeira resposta de cada aluno.", false, "Não há esse filtro: o resultado cresce, não diminui."]]},
  "BD.09": {"f": "lacunas", "p": "Complete: subconsulta que devolve várias linhas.", "t": "Para achar as questões de matérias da banca FGV: WHERE materia_id {{IN}} (SELECT id FROM materias WHERE banca = 'FGV'). Com = no lugar, a consulta dá {{erro}} quando a subconsulta devolve {{mais de uma}} linha.", "x": ["=", "uma só", "certo"], "por": "= compara com um valor só. Quando a subconsulta pode devolver vários, use IN ou EXISTS."},
  "BD.10": {"f": "erro", "p": "Você vai juntar duas listas de alunos com UNION. Uma frase está errada. Toque nela.", "t": ["As duas consultas precisam ter o mesmo número de colunas.", "As colunas correspondentes precisam ter tipos compatíveis.", "UNION ALL mantém as linhas repetidas; UNION tira.", "A ordem das colunas não importa: o banco casa as colunas pelo nome."], "e": 3, "por": "O UNION casa as colunas pela posição, não pelo nome. Pôr nome e email numa consulta e email e nome na outra mistura as colunas."},
  "BD.18": {"f": "escolha", "p": "Na álgebra relacional, qual operação escolhe colunas?", "o": [["A projeção (π): escolhe colunas, como o SELECT nome, email.", true, "A seleção (σ) escolhe linhas, como o WHERE. O nome SELECT do SQL é que confunde."], ["A seleção (σ), porque o SQL chama de SELECT.", false, "A seleção da álgebra escolhe linhas (equivale ao WHERE). Quem escolhe colunas é a projeção."], ["A junção (⋈), porque junta colunas.", false, "A junção combina linhas de duas relações. Escolher colunas é projeção."]]},
  "BD.12": {"f": "escolha", "p": "Um aluno estuda várias matérias e cada matéria tem vários alunos. Como modelar?", "o": [["Uma tabela de ligação (aluno_id, materia_id), com uma linha para cada par.", true, "Relacionamento N:M vira uma terceira tabela; cada linha liga um aluno a uma matéria."], ["Uma coluna materias no aluno, com \"BD, EST, LOG\".", false, "Uma lista dentro de uma coluna impede filtrar, contar e ligar direito, e fere a primeira forma normal."], ["Uma coluna materia_id em alunos.", false, "Isso só permite uma matéria por aluno: serve para 1:N, não para N:M."]]},
  "BD.13": {"f": "lacunas", "p": "Complete: o problema que a normalização resolve.", "t": "Se o nome da matéria fosse repetido em cada linha de questoes, corrigir o nome exigiria mudar {{muitas}} linhas, e esquecer uma deixaria o dado {{desencontrado}}. A normalização guarda cada fato num lugar {{só}}.", "x": ["poucas", "apagado", "vários"], "por": "As formas normais existem para evitar dado repetido que se desencontra (anomalias de inserção, atualização e remoção)."},
  "BD.14": {"f": "erro", "p": "Você quer apagar só as respostas do aluno 3. Uma frase está errada. Toque nela.", "t": ["DELETE FROM respostas WHERE aluno_id = 3; apaga só as linhas do aluno 3.", "Vale rodar antes SELECT COUNT(*) FROM respostas WHERE aluno_id = 3; para ver quantas linhas sairão.", "DELETE FROM respostas; sem WHERE também apaga só o aluno 3, se ele foi o último consultado.", "Dentro de uma transação, dá para desfazer com ROLLBACK antes do COMMIT."], "e": 2, "por": "Sem WHERE, o DELETE apaga a tabela inteira. O banco não lembra de consultas anteriores."},
  "BD.15": {"f": "escolha", "p": "Você quer, em cada linha de respostas, o total de acertos do aluno, sem perder linha nenhuma. O que usar?", "o": [["SUM(acertou) OVER (PARTITION BY aluno_id)", true, "A função de janela calcula por grupo e mantém todas as linhas; o GROUP BY resumiria cada aluno numa linha só."], ["GROUP BY aluno_id com SUM(acertou)", false, "O GROUP BY devolve uma linha por aluno: as respostas individuais somem."], ["ORDER BY aluno_id", false, "Ordenar não calcula nada; só muda a ordem das linhas."]]},
  "BD.16": {"f": "ordem", "p": "Ponha na ordem uma transferência de pontos entre dois alunos feita com segurança.", "t": ["BEGIN", "Tirar os pontos do primeiro aluno", "Somar os pontos no segundo aluno", "COMMIT, se as duas partes deram certo"], "por": "A transação faz as duas mudanças valerem juntas ou nenhuma. Se algo falhar no meio, ROLLBACK desfaz tudo e o banco não fica pela metade."},
  "BD.17": {"f": "escolha", "p": "Por que não criar índice em todas as colunas da tabela respostas?", "o": [["Cada índice ocupa espaço e precisa ser atualizado a cada INSERT, UPDATE e DELETE, deixando as gravações mais lentas.", true, "Índice é bom para consultas frequentes e seletivas. Em excesso, encarece as gravações sem ajudar as leituras."], ["Porque índice só funciona em colunas de texto.", false, "Índice funciona em números, datas e textos."], ["Porque o banco só aceita um índice por tabela.", false, "Pode haver vários; o problema é o custo de mantê-los."]]},
  "BD.19": {"f": "lacunas", "p": "Complete: o que uma view guarda.", "t": "CREATE VIEW taxa_por_materia AS SELECT … guarda a {{consulta}}, não os dados. Cada vez que alguém usa a view, a consulta roda de {{novo}}, por isso ela sempre mostra os dados {{atuais}}.", "x": ["tabela", "antigos", "cópia"], "por": "A view é uma consulta com nome. Quem precisa de cópia guardada usa outra coisa (uma tabela ou uma view materializada)."},
  "BD.20": {"f": "escolha", "p": "No data warehouse, a tabela de fatos repete o nome da matéria em vez de só o id. Isso está errado?", "o": [["Não: no modelo estrela, a repetição é proposital, para as consultas de análise ficarem simples e rápidas.", true, "O banco transacional normaliza para gravar sem anomalias; o analítico desnormaliza para ler rápido."], ["Sim: todo banco deve estar na terceira forma normal.", false, "A regra vale para o banco transacional. O analítico tem outro objetivo: leitura rápida."], ["Sim, porque o data warehouse não pode ter texto.", false, "Pode ter texto; dimensões costumam ter muitos atributos descritivos."]]},
  "CMP.01": {"f": "escolha", "p": "Em Python, 0.1 + 0.2 == 0.3 dá False. Como comparar valores em dinheiro com segurança?", "o": [["Guardar em centavos inteiros (10 + 20 == 30) ou usar Decimal.", true, "O float guarda frações em base 2, e 0,1 não tem representação exata; centavos inteiros não têm esse problema."], ["Usar float mesmo; o False é um bug do Python.", false, "Não é bug: é como o padrão IEEE 754 representa decimais em base 2. Acontece em qualquer linguagem."], ["Arredondar com int() antes de somar.", false, "int() corta as casas decimais: 0,1 viraria 0 e a conta perderia os centavos."]]},
  "CMP.02": {"f": "lacunas", "p": "Complete: caracteres e bytes.", "t": "Em UTF-8, a letra a ocupa {{1}} byte, mas ã ocupa {{2}}. Quando um arquivo UTF-8 é lido como Latin-1, o ã aparece como “Ã£”: é o {{mojibake}}, o acento quebrado.", "x": ["4", "ASCII", "8"], "por": "Cada caractere não ocupa necessariamente um byte. Ler com a codificação errada troca os bytes de lugar e quebra os acentos."},
  "CMP.03": {"f": "escolha", "p": "Qual é o resultado de 1 XOU 1 (ou exclusivo)?", "o": [["0, porque o ou exclusivo só dá 1 quando as entradas são diferentes.", true, "No OU comum, 1 ou 1 dá 1; no OU exclusivo, entradas iguais dão 0."], ["1, igual ao OU comum.", false, "Esse é o OU comum. O exclusivo exige que só uma das entradas seja 1."], ["2, porque soma as entradas.", false, "Portas lógicas trabalham só com 0 e 1; não há 2. (Na soma binária, 1 + 1 dá 0 e vai 1, e o 0 vem justamente do XOU.)"]]},
  "CMP.04": {"f": "erro", "p": "O celular fica lento com muitos apps abertos. Uma frase está errada. Toque nela.", "t": ["A RAM guarda os apps que estão abertos agora.", "Quando a RAM enche, o sistema fecha apps ou usa o armazenamento, que é bem mais lento.", "Comprar um celular com mais armazenamento resolve, porque o armazenamento segura os apps abertos.", "O cache, dentro da CPU, é ainda mais rápido que a RAM, e bem menor."], "e": 2, "por": "O armazenamento guarda arquivos e apps instalados; quem segura os apps abertos é a RAM. Mais armazenamento não deixa o celular mais rápido."},
  "CMP.05": {"f": "lacunas", "p": "Complete: caminho relativo.", "t": "open(\"dados/notas.csv\") usa um caminho {{relativo}}: ele parte da pasta em que você está quando {{roda}} o script, não da pasta onde o script está. Rodando de outra pasta, o arquivo “some”. Um caminho {{absoluto}}, que começa da raiz, não depende disso.", "x": ["oculto", "salva", "curto"], "por": "O caminho relativo é resolvido a partir do diretório atual. Para não depender dele, monte o caminho a partir da pasta do script (com pathlib) ou use um absoluto."},
  "CMP.06": {"f": "ordem", "p": "Você digita o endereço de um site e aperta Enter. Ponha na ordem o que acontece.", "t": ["O DNS traduz o nome do site para um endereço IP", "O navegador abre a conexão com o servidor nesse IP", "O navegador envia uma requisição HTTP GET", "O servidor responde com um código de status e a página"], "por": "A internet são computadores trocando mensagens por protocolos: nome vira IP (DNS), conecta, pede (HTTP) e recebe a resposta (como 200 ou 404)."},
  "CMP.07": {"f": "escolha", "p": "O Python é interpretado. Ele traduz o seu código antes de rodar?", "o": [["Sim: o CPython compila o código para bytecode e a máquina virtual dele executa esse bytecode.", true, "A tradução existe, só fica escondida (são os arquivos .pyc). O Java faz o mesmo com a JVM, mas a etapa é explícita."], ["Não: o processador lê o texto do .py diretamente.", false, "O processador não entende Python: alguém precisa traduzir. No CPython, vira bytecode."], ["Sim: gera um .exe, igual ao C.", false, "O C gera código de máquina; o Python gera bytecode para a máquina virtual dele, não um executável."]]},
  "MAT.01": {"f": "escolha", "p": "A = alunos que fizeram BD; B = alunos que fizeram EST. O que é A ∩ B?", "o": [["Os alunos que fizeram as duas matérias.", true, "Interseção: está nos dois conjuntos. A união (A ∪ B) seria quem fez pelo menos uma."], ["Os alunos que fizeram pelo menos uma das duas.", false, "Essa é a união. Interseção exige estar nos dois."], ["Os alunos que fizeram BD mas não EST.", false, "Essa é a diferença A − B."]]},
  "MAT.02": {"f": "lacunas", "p": "Complete: negar “todo”.", "t": "A frase “todo aluno acertou a questão” é falsa se {{pelo menos um}} aluno errou. Por isso, a negação de “todo aluno acertou” é “algum aluno {{não}} acertou”, e não “{{nenhum}} aluno acertou”.", "x": ["todos os", "sempre", "cada"], "por": "Para derrubar um “todo” basta um contraexemplo. “Nenhum acertou” é uma afirmação bem mais forte do que a negação."},
  "MAT.03": {"f": "escolha", "p": "Uma senha de 3 dígitos distintos, de 0 a 9. Como contar as possibilidades?", "o": [["Arranjo: 10 × 9 × 8 = 720, porque a ordem importa (123 e 321 são senhas diferentes).", true, "Quando a ordem importa, é arranjo (ou permutação); quando não importa, como escolher 2 sabores de pizza, é combinação."], ["Combinação: 120, porque são 3 dígitos escolhidos de 10.", false, "Combinação ignora a ordem, mas na senha a ordem muda tudo: 123 não é 321."], ["10 × 10 × 10 = 1000.", false, "Isso permitiria repetir dígitos; o enunciado pede dígitos distintos."]]},
  "EST.01": {"f": "erro", "p": "Num questionário, a satisfação foi marcada como pequena, média ou grande. Uma frase está errada. Toque nela.", "t": ["A satisfação é uma variável qualitativa ordinal: tem ordem, mas não tem distância medida.", "Dá para contar quantos marcaram cada opção.", "Dá para dizer qual é a mediana, porque as categorias têm ordem.", "Dá para tirar a média, trocando pequena, média e grande por 1, 2 e 3."], "e": 3, "por": "Os números 1, 2 e 3 são só rótulos: nada garante que a distância de pequena para média seja igual à de média para grande. Com ordinal, use contagens e mediana."},
  "EST.02": {"f": "escolha", "p": "Os salários de uma equipe são 3, 3, 3, 4 e 50 mil. Qual medida descreve melhor o salário típico?", "o": [["A mediana (3 mil), porque o valor extremo puxa a média para cima.", true, "A média dá 12,6 mil, que ninguém da equipe ganha. Com valores extremos, a mediana resume melhor."], ["A média (12,6 mil), porque usa todos os valores.", false, "Usar todos os valores é justamente o problema: o 50 mil arrasta a média para longe do típico."], ["A amplitude (47 mil), porque mostra a diferença.", false, "A amplitude mede espalhamento, não o valor típico."]]},
  "EST.03": {"f": "lacunas", "p": "Complete: a pergunta certa sobre um exame.", "t": "A chance de o exame dar positivo dado que a pessoa está doente é a {{sensibilidade}}. A chance de a pessoa estar doente dado que deu positivo é outra coisa, e depende também de quão {{comum}} é a doença. Para passar de uma para a outra, usa-se o teorema de {{Bayes}}.", "x": ["média", "rara de exame", "Pearson"], "por": "P(positivo | doente) e P(doente | positivo) são diferentes. Numa doença rara, mesmo um exame bom gera muitos positivos falsos."},
  "EST.04": {"f": "escolha", "p": "Num jogo, você ganha 10 reais com chance de 1/2 e perde 4 com chance de 1/2. O valor esperado é 3 reais. O que isso quer dizer?", "o": [["Que, em muitas jogadas, o ganho médio por jogada fica perto de 3 reais.", true, "O valor esperado é a média de muitas repetições. Numa jogada só, você ganha 10 ou perde 4; nunca ganha exatamente 3."], ["Que na próxima jogada você vai ganhar 3 reais.", false, "Numa jogada os resultados possíveis são +10 ou −4; 3 nem é um deles."], ["Que você ganha em 3 de cada 10 jogadas.", false, "Valor esperado não é frequência de vitórias; é a média ponderada dos ganhos."]]},
  "EST.05": {"f": "escolha", "p": "Qual destas variáveis costuma ter distribuição assimétrica, e não normal?", "o": [["A renda das pessoas: a maioria ganha pouco e poucas ganham muito.", true, "Renda, tempo de espera e contagens costumam ter cauda longa à direita. Supor normal aí erra as probabilidades."], ["A altura de adultos de um mesmo sexo.", false, "A altura é um exemplo clássico de distribuição próxima da normal."], ["O erro de medida de uma balança bem calibrada.", false, "Erros de medida pequenos e independentes tendem à normal."]]},
  "EST.06": {"f": "erro", "p": "Uma enquete no site de um time ouviu 100 mil torcedores. Uma frase está errada. Toque nela.", "t": ["Quem responde a enquete se escolheu sozinho, o que pode enviesar o resultado.", "Com 100 mil respostas, a enquete representa bem toda a população do país.", "Uma amostra aleatória de mil pessoas pode representar melhor que 100 mil voluntários.", "Amostra grande diminui o erro aleatório, mas não corrige viés de seleção."], "e": 1, "por": "Tamanho não corrige viés: 100 mil torcedores de um time são uma amostra enviesada do país. O que torna a amostra boa é como ela é escolhida."},
  "EST.09": {"f": "escolha", "p": "O que o bootstrap faz?", "o": [["Sorteia, com reposição, muitas amostras a partir da amostra que você já tem, para ver como a estatística varia.", true, "Ele reaproveita os dados existentes para estimar a incerteza, sem fórmula. Não cria informação nova sobre a população."], ["Cria dados novos da população, aumentando a amostra.", false, "O bootstrap não gera dados novos: só recombina os que existem."], ["Remove os valores atípicos antes da análise.", false, "Isso é limpeza de dados, outra coisa."]]},
  "EST.07": {"f": "lacunas", "p": "Complete: como ler um intervalo de confiança de 95%.", "t": "O 95% descreve o {{método}}: em cerca de 95% das amostras possíveis, o intervalo calculado contém o valor verdadeiro. Um intervalo já calculado {{contém}} ou não contém esse valor. O que muda de uma amostra para outra é o {{intervalo}}, e não o valor verdadeiro.", "x": ["valor verdadeiro", "sempre", "p-valor"], "por": "O valor verdadeiro é fixo; o que varia de amostra para amostra é o intervalo. Por isso o 95% é a taxa de acerto do método, e não a chance de um intervalo específico."},
  "EST.08": {"f": "erro", "p": "Um teste A/B deu p-valor = 0,03. Uma frase está errada. Toque nela.", "t": ["Se não houvesse diferença real, resultados tão extremos quanto este apareceriam em cerca de 3% das vezes.", "Com nível de significância de 5%, rejeita-se a hipótese nula.", "Há 97% de chance de a versão B ser melhor.", "Significativo não quer dizer importante: a diferença pode ser pequena demais para valer a pena."], "e": 2, "por": "O p-valor não é a probabilidade da hipótese. Ele mede quão surpreendente seria o dado se a hipótese nula fosse verdadeira."},
  "EST.10": {"f": "escolha", "p": "Cidades com mais sorveterias têm mais afogamentos. O que se conclui?", "o": [["Nada sobre causa: o calor aumenta as duas coisas (é uma variável de confusão).", true, "Correlação não é causa. Para falar de causa, é preciso controlar a confusão ou fazer um experimento aleatorizado."], ["Que sorvete causa afogamento.", false, "A correlação existe, mas a causa comum é o verão: mais calor, mais sorvete e mais gente na água."], ["Que a correlação é falsa e deve ser ignorada.", false, "A correlação é real; só não é causal. Ela pode ser útil para prever, não para explicar."]]},
  "EST.11": {"f": "escolha", "p": "Uma regressão de salário por anos de estudo usou dados de 8 a 20 anos e deu coeficiente 300. O que se pode dizer?", "o": [["Dentro da faixa observada, cada ano a mais de estudo está associado, em média, a 300 reais a mais de salário.", true, "O coeficiente descreve associação na faixa dos dados. Prever para 40 anos de estudo é extrapolar, e ler como causa exige outro desenho de estudo."], ["Estudar um ano a mais causa 300 reais a mais de salário.", false, "Regressão com dados observados mostra associação; causa exige controlar confusões ou experimento."], ["Quem estudar 40 anos ganhará 12 mil a mais.", false, "40 anos está fora da faixa dos dados (8 a 20): o modelo não sabe o que acontece lá."]]},
  "EST.12": {"f": "lacunas", "p": "Complete: prever uma probabilidade.", "t": "Para prever a chance de um aluno ser aprovado, a regressão {{linear}} pode dar valores acima de {{1}} ou abaixo de 0, o que não faz sentido para probabilidade. A regressão {{logística}} mantém a previsão entre 0 e 1.", "x": ["logarítmica", "100", "normal"], "por": "Probabilidade vive entre 0 e 1. A logística transforma a combinação linear numa curva em S que respeita esse limite."},
  "ALG.01": {"f": "escolha", "p": "Um algoritmo é O(n). O que isso diz?", "o": [["Que o tempo cresce na mesma proporção da entrada: com o dobro de dados, cerca do dobro de operações.", true, "A notação O descreve o crescimento, não o tempo em segundos. Os segundos dependem da máquina; o crescimento, do algoritmo."], ["Que ele leva n segundos para rodar.", false, "O(n) não mede segundos: mede como o número de operações cresce quando n cresce."], ["Que ele é sempre mais rápido que um O(n²).", false, "Para entradas pequenas, um O(n²) simples pode ser mais rápido; a vantagem do O(n) aparece quando n cresce."]]},
  "ED.01": {"f": "lacunas", "p": "Complete: tipo abstrato e implementação.", "t": "Uma fila é definida pelas {{operações}} que oferece (entrar no fim, sair do começo) e pelo custo de cada uma. Isso é o tipo {{abstrato}}. Guardar os itens num vetor ou numa lista ligada é a {{implementação}}, que pode mudar sem mudar a ideia.", "x": ["variáveis", "concreto", "interface gráfica"], "por": "O tipo abstrato diz o que a estrutura faz; a implementação diz como. Separar os dois permite trocar o como sem quebrar quem usa."},
  "ED.02": {"f": "erro", "p": "lista = [10 itens] em Python. Uma frase está errada. Toque nela.", "t": ["lista[0] é o primeiro item e lista[9] é o último.", "Acessar lista[5] custa o mesmo que acessar lista[0]: O(1).", "lista[10] devolve o décimo item.", "Inserir no começo com insert(0, x) obriga a deslocar todos os itens: O(n)."], "e": 2, "por": "Com 10 itens, os índices vão de 0 a 9. lista[10] não existe e dá IndexError."},
  "ED.04": {"f": "ordem", "p": "Numa pilha vazia, você empilha A, B e C, desempilha uma vez e depois empilha D. Ponha o conteúdo na ordem, do fundo para o topo.", "t": ["A", "B", "D"], "por": "Pilha é LIFO: o último a entrar (C) é o primeiro a sair. Depois, D entra no topo, em cima de B."},
  "ED.05": {"f": "escolha", "p": "Uma fila de atendimento com milhares de pessoas usa lista.pop(0) para chamar a próxima. Qual o problema?", "o": [["Cada pop(0) desloca todos os itens restantes (O(n)); com collections.deque, popleft() é O(1).", true, "A fila tira do começo; a lista do Python é rápida só no fim. O deque é feito para as duas pontas."], ["Nenhum: pop(0) é tão rápido quanto pop().", false, "pop() tira do fim sem deslocar nada; pop(0) desloca todos os outros."], ["pop(0) tira a última pessoa, e a fila fica injusta.", false, "pop(0) tira a primeira, o comportamento certo de fila; o problema é o custo, não a ordem."]]},
  "ED.03": {"f": "lacunas", "p": "Complete: inserir no fim de uma lista ligada que guarda head e tail.", "t": "Para inserir no fim, crie o nó novo, faça o {{tail}} atual apontar para ele e depois atualize o tail para o {{nó novo}}. Esquecer esse último passo deixa o tail apontando para o nó {{antigo}}, e a próxima inserção se perde.", "x": ["head", "primeiro", "vazio"], "por": "Na lista ligada, cada inserção precisa manter os ponteiros de controle (head e tail) certos. É o erro mais comum de implementação."},
  "ALG.04": {"f": "erro", "p": "fat(3) = 3 * fat(2), fat(1) = 1. Uma frase está errada. Toque nela.", "t": ["fat(3) chama fat(2), que chama fat(1).", "fat(1) é o caso base: devolve 1 sem chamar ninguém.", "O resultado 6 já está pronto na primeira chamada, antes de fat(2) responder.", "Na volta, fat(2) devolve 2 * 1 = 2 e fat(3) devolve 3 * 2 = 6."], "e": 2, "por": "O resultado é montado na volta: fat(3) só consegue multiplicar depois que fat(2) responde. A ida empilha as chamadas; a volta calcula."},
  "ALG.02": {"f": "escolha", "p": "Quando a busca binária funciona?", "o": [["Quando a lista está ordenada e permite pular direto para o meio (acesso por índice).", true, "A busca binária descarta metade a cada passo comparando com o meio; sem ordem, essa comparação não diz para que lado ir."], ["Em qualquer lista, desde que seja grande.", false, "Sem ordenação, comparar com o meio não diz em que metade está o valor."], ["Numa lista ligada ordenada, tão rápido quanto num vetor.", false, "Na lista ligada, chegar ao meio exige percorrer metade dos nós: a vantagem some."]]},
  "ED.06": {"f": "lacunas", "p": "Complete: o que acontece quando a tabela hash cresce.", "t": "A posição de cada chave depende do hash dela e do {{tamanho}} da tabela. Quando a tabela dobra, é preciso {{recalcular}} a posição de todas as chaves. Graças a esse cuidado, a busca num dict continua O({{1}}) em média.", "x": ["nome", "manter", "n"], "por": "A posição é calculada como hash modulo tamanho; mudou o tamanho, mudam as posições. Por isso o crescimento custa caro de vez em quando."},
  "ALG.03": {"f": "escolha", "p": "Qual ordenação simples é a melhor para uma lista quase ordenada?", "o": [["A inserção, que faz pouco trabalho quando cada item já está perto do lugar certo.", true, "Na lista quase ordenada, a inserção chega perto de O(n). A seleção continua fazendo todas as comparações."], ["A seleção, porque é sempre a mais rápida.", false, "A seleção faz o mesmo número de comparações em qualquer entrada, mesmo já ordenada."], ["Tanto faz: os métodos simples se equivalem.", false, "Todos são O(n²) no pior caso, mas se comportam diferente; com lista quase ordenada, a inserção ganha."]]},
  "ALG.05": {"f": "erro", "p": "Uma frase sobre o quicksort está errada. Toque nela.", "t": ["Ele escolhe um pivô e separa os menores e os maiores que ele.", "Depois ordena cada lado do mesmo jeito.", "Ele é sempre O(n log n), qualquer que seja o pivô.", "Escolher sempre o primeiro item como pivô numa lista já ordenada leva a O(n²)."], "e": 2, "por": "O quicksort é O(n log n) em média, mas com pivô ruim (lados desiguais) cai para O(n²). Por isso se usa pivô aleatório ou a mediana de três."},
  "ALG.06": {"f": "escolha", "p": "Quando a ordenação por contagem não vale a pena?", "o": [["Quando os valores vão de 0 a 1 bilhão: a tabela de contagem teria um bilhão de posições.", true, "A contagem é ótima com poucos valores possíveis (notas de 0 a 10, idades). Com valores muito espalhados, a memória explode."], ["Quando há muitos itens repetidos.", false, "Repetição é ótima para a contagem: ela só soma um no contador."], ["Quando os valores são inteiros pequenos.", false, "Esse é justamente o melhor caso dela."]]},
  "ED.07": {"f": "ordem", "p": "Numa árvore com raiz R, filho esquerdo E e filho direito D, ponha na ordem a visita do percurso em pós-ordem.", "t": ["E (filho esquerdo)", "D (filho direito)", "R (raiz)"], "por": "O nome diz quando a raiz é visitada: pré (antes dos filhos), em (no meio) ou pós (depois dos dois filhos)."},
  "ED.10": {"f": "escolha", "p": "Num heap mínimo, o que é sempre verdade?", "o": [["Cada pai é menor ou igual aos filhos, então o menor de todos está na raiz.", true, "O heap só garante a relação pai e filhos. Por isso o menor sai rápido, mas não dá para buscar qualquer valor rápido."], ["O filho da esquerda é sempre menor que o da direita.", false, "Essa é a regra da árvore de busca; o heap não compara irmãos."], ["Os itens ficam em ordem crescente, lidos da esquerda para a direita.", false, "O heap não guarda a ordem completa; só garante o menor no topo."]]},
  "ED.08": {"f": "lacunas", "p": "Complete: árvore de busca que degenera.", "t": "Inserindo 1, 2, 3, 4, 5 nessa ordem numa árvore binária de busca comum, cada novo valor vai sempre para a {{direita}}. A árvore vira uma {{lista}} de nós, com altura 5, e a busca custa O({{n}}) em vez de O(log n).", "x": ["esquerda", "raiz", "1"], "por": "A árvore de busca comum não se balanceia sozinha: com valores em ordem, ela degenera numa lista."},
  "ED.09": {"f": "escolha", "p": "Para que servem as rotações numa árvore AVL?", "o": [["Para manter a altura perto de log n depois de cada inserção ou remoção, e a busca continuar rápida.", true, "As rotações reorganizam os nós sem quebrar a ordem; o objetivo é a altura baixa."], ["Para ordenar os valores da árvore.", false, "A ordem já é garantida pela regra da árvore de busca; a rotação cuida da altura."], ["Para deixar a árvore com o mesmo número de nós em cada nível.", false, "Ela tolera diferença de altura de até 1 entre os lados; não exige níveis cheios."]]},
  "ED.11": {"f": "erro", "p": "Numa rede social, uma frase sobre o grafo está errada. Toque nela.", "t": ["Seguir alguém é uma aresta dirigida: A seguir B não faz B seguir A.", "Amizade mútua é uma aresta sem direção.", "Se A segue B, então B segue A automaticamente, porque toda aresta vale nos dois sentidos.", "Num mapa de ruas, o peso da aresta pode ser a distância."], "e": 2, "por": "Seguir tem direção: é grafo dirigido. Só nas relações mútuas a aresta vale nos dois sentidos."},
  "ALG.09": {"f": "escolha", "p": "Você quer o caminho mais curto em quilômetros num mapa em que cada rua tem uma distância. Qual algoritmo usar?", "o": [["Dijkstra, porque as arestas têm pesos diferentes.", true, "A busca em largura acha o caminho com menos ruas, não o mais curto em distância. Com pesos, é Dijkstra."], ["Busca em largura, porque sempre acha o caminho mais curto.", false, "A largura minimiza o número de arestas, o que só coincide com a distância se todas tiverem o mesmo peso."], ["Busca em profundidade, porque vai mais longe primeiro.", false, "A profundidade nem garante o menor número de arestas, quanto menos a menor distância."]]},
  "ALG.07": {"f": "lacunas", "p": "Complete: quando o guloso falha.", "t": "Para dar 6 centavos de troco com moedas de 1, 3 e 4, o guloso pega a maior primeiro: 4 + 1 + 1, ou {{três}} moedas. Mas 3 + 3 resolve com {{duas}}. Escolher sempre o melhor agora nem sempre dá o {{melhor}} no fim.", "x": ["uma", "quatro", "pior"], "por": "O guloso funciona quando o problema tem a propriedade certa (como as moedas do real). Fora disso, é preciso testar ou usar programação dinâmica."},
  "ALG.08": {"f": "escolha", "p": "Por que o fib(n) recursivo simples é tão lento, e como a programação dinâmica resolve?", "o": [["Ele recalcula os mesmos subproblemas muitas vezes; guardando cada resultado numa tabela (memorização), cada um é calculado uma vez só.", true, "Subproblemas que se repetem são a marca da programação dinâmica: calcula uma vez, consulta nas outras."], ["Porque recursão é sempre lenta; basta trocar por um laço qualquer.", false, "O problema não é a recursão em si, e sim recalcular o mesmo subproblema. Recursão com memória fica rápida."], ["Porque os números ficam grandes demais para o computador.", false, "O tamanho do número não é o gargalo; o número de chamadas repetidas é."]]},
  "ED.12": {"f": "escolha", "p": "Por que df[\"nota\"].mean() é rápido no pandas?", "o": [["Porque o pandas guarda cada coluna junta na memória, e a conta corre sobre ela de uma vez, em código otimizado.", true, "O armazenamento por coluna é o que torna as operações na coluna inteira rápidas."], ["Porque o pandas guarda os dados linha por linha, como uma planilha.", false, "Ele guarda por coluna; é isso que permite a operação em bloco."], ["Porque o pandas usa um laço for por dentro, em Python.", false, "Por dentro ele usa código compilado sobre a coluna inteira, não um laço em Python."]]},
  "ALG.10": {"f": "ordem", "p": "Você quer saber se a versão vetorizada é mesmo mais rápida. Ponha os passos na ordem.", "t": ["Gerar entradas de tamanhos diferentes (mil, 10 mil, 100 mil)", "Medir cada versão várias vezes com timeit", "Comparar como o tempo cresce com o tamanho", "Concluir só depois de ver a tendência"], "por": "Uma medida só, com entrada pequena, engana. O que interessa é como o tempo cresce quando a entrada cresce."},
  "POO.01": {"f": "escolha", "p": "Você escreveu class Conta: com saldo e depositar(). Já existe alguma conta?", "o": [["Não: a classe é o molde. Uma conta só existe quando você a cria, com c = Conta().", true, "Instanciar é criar o objeto a partir da classe. Cada Conta() cria uma conta nova, com o seu próprio saldo."], ["Sim: escrever a classe já cria uma conta.", false, "A classe só descreve como uma conta é; nenhuma existe até ser instanciada."], ["Sim: existe uma conta para cada método da classe.", false, "Métodos são comportamentos do molde; não criam objetos."]]},
  "POO.02": {"f": "lacunas", "p": "Complete: encapsular o saldo.", "t": "Se qualquer parte do código pode escrever conta.saldo = -500, a regra “o saldo não fica negativo” deixa de valer. Encapsular é esconder o atributo e oferecer {{métodos}}, como sacar(valor), que {{conferem}} a regra antes de mudar o saldo. Assim o objeto nunca fica num estado {{inválido}}.", "x": ["atributos públicos", "ignoram", "salvo"], "por": "O encapsulamento protege a invariante: quem quiser mudar o estado passa pela porta que confere a regra."},
  "POO.03": {"f": "erro", "p": "Uma frase sobre herança está errada. Toque nela.", "t": ["ContaPoupanca herda de Conta, porque uma poupança é uma conta.", "A subclasse pode sobrescrever um método para mudar o comportamento.", "super() chama a versão do método na superclasse.", "Carro deve herdar de Motor para reaproveitar o método ligar(), porque usa o mesmo código."], "e": 3, "por": "Herança pede a relação “é um”. Carro não é um motor: carro tem um motor. Nesse caso, use composição (um atributo motor)."},
  "POO.04": {"f": "escolha", "p": "O sistema cobra por Pix, boleto e cartão. Qual desenho é o polimórfico?", "o": [["Cada forma de pagamento tem o seu método pagar(valor), e o sistema só chama pagamento.pagar(valor).", true, "Polimorfismo é tratar tipos diferentes pela mesma interface: entra um novo meio de pagamento sem mexer no código que cobra."], ["Um if para cada caso: se for Pix faça isto, se for boleto faça aquilo.", false, "Funciona, mas cada meio novo obriga a mexer nesse if, em todos os lugares em que ele aparece."], ["Uma classe só, Pagamento, com um atributo tipo e todo o código dentro dela.", false, "Concentra tudo num lugar e volta ao mesmo encadeamento de ifs."]]},
  "POO.05": {"f": "lacunas", "p": "Complete: composição em vez de herança.", "t": "Em vez de criar CarroEletricoComTetoSolar herdando de três classes, monte o carro {{juntando}} objetos: um motor, um teto. Isso é {{composição}}. A interface (o {{contrato}}) diz o que cada peça precisa saber fazer, sem amarrar a hierarquia.", "x": ["herdando", "herança", "construtor"], "por": "Hierarquias longas ficam rígidas. Compor objetos que respeitam um contrato deixa trocar uma peça sem refazer a árvore."},
  "POO.06": {"f": "escolha", "p": "Em Java, a e b são Strings com o mesmo texto. Qual comparação é a certa?", "o": [["a.equals(b), que compara o conteúdo.", true, "Com objetos, == compara se são o mesmo objeto na memória; equals compara o conteúdo. É pegadinha frequente em prova."], ["a == b, que compara o conteúdo do texto.", false, "Em Java, == com objetos compara referências: dois textos iguais podem estar em objetos diferentes."], ["a = b, que confere se são iguais.", false, "= é atribuição: guardaria b em a."]]},
  "POO.07": {"f": "escolha", "p": "Você precisa achar rapidamente o aluno pelo número de matrícula, entre milhares. Que coleção usar?", "o": [["HashMap em Java (dict em Python), com a matrícula como chave.", true, "Busca por chave num mapa é O(1) em média; numa lista, seria preciso percorrer até achar."], ["ArrayList em Java (list em Python), percorrendo até achar.", false, "Funciona, mas cada busca custa O(n): com milhares, fica lento."], ["HashSet em Java (set em Python).", false, "O conjunto diz se a matrícula existe, mas não guarda o aluno associado a ela."]]},
  "POO.08": {"f": "erro", "p": "A classe Relatorio lê o banco, calcula, formata o PDF e envia o e-mail. Uma frase está errada. Toque nela.", "t": ["Ela tem responsabilidades demais: mudar o formato do PDF obriga a mexer na mesma classe que lê o banco.", "Separar em leitor, calculadora, formatador e envio aumenta a coesão de cada parte.", "Juntar tudo numa classe só diminui o acoplamento, porque fica tudo no mesmo lugar.", "Com partes separadas, dá para testar o cálculo sem enviar e-mail."], "e": 2, "por": "Tudo no mesmo lugar aumenta o acoplamento: qualquer mudança mexe em tudo. O desejável é alta coesão e baixo acoplamento."},
  "ENG.01": {"f": "escolha", "p": "No terminal, rm notas.csv apaga o arquivo. Dá para recuperar pela lixeira?", "o": [["Não: o rm apaga direto, sem lixeira. Antes de apagar, confira com ls o que vai sair.", true, "No terminal, apagar é para sempre. Por isso os profissionais conferem antes e mantêm cópia (e o Git)."], ["Sim: o arquivo vai para a lixeira, como no explorador de arquivos.", false, "A lixeira é do ambiente gráfico; o rm não passa por ela."], ["Sim, com o comando undo.", false, "Não existe undo no terminal."]]},
  "ENG.04": {"f": "lacunas", "p": "Complete: por que usar ambiente virtual.", "t": "Cada projeto ganha o seu {{ambiente virtual}}, com as próprias versões das bibliotecas. Assim, atualizar o pandas num projeto não {{quebra}} o outro. O arquivo de dependências (requirements ou pyproject) deixa outra pessoa {{recriar}} o mesmo ambiente.", "x": ["Python do sistema", "acelera", "apagar"], "por": "Instalar tudo no Python do sistema mistura as versões de todos os projetos: um update num lugar quebra outro."},
  "ENG.05": {"f": "erro", "p": "Num notebook, você rodou as células 1, 3 e 2, nessa ordem, e tudo funcionou. Uma frase está errada. Toque nela.", "t": ["O resultado depende do estado criado pela ordem em que as células rodaram.", "Se outra pessoa rodar de cima para baixo, pode dar erro ou outro resultado.", "Como funcionou, o notebook está certo e vai funcionar em qualquer ordem.", "Antes de entregar, reinicie e rode tudo do começo: Restart & Run All."], "e": 2, "por": "O notebook guarda estado oculto. Só dá para confiar no resultado quando ele funciona rodando tudo do zero, em ordem."},
  "ENG.02": {"f": "escolha", "p": "Qual destes commits conta melhor a história do projeto?", "o": [["Um commit por mudança, com mensagem como “Corrige média que ignorava respostas em branco”.", true, "Commits pequenos e bem descritos deixam ver o que mudou e desfazer só o que deu errado."], ["Um commit no fim do dia com tudo e a mensagem “ajustes”.", false, "Mistura mudanças sem relação e não diz nada: desfazer uma parte vira cirurgia."], ["Nenhum commit até o projeto terminar, para o histórico ficar limpo.", false, "Sem commits, não há como voltar a uma versão que funcionava."]]},
  "ENG.03": {"f": "ordem", "p": "Seu merge deu conflito no arquivo analise.py. Ponha na ordem o que fazer.", "t": ["Abrir o arquivo e achar as marcas <<<<<<<, ======= e >>>>>>>", "Decidir o que fica: a sua versão, a outra ou uma combinação", "Apagar as marcas e testar o código", "git add e git commit para concluir o merge"], "por": "Conflito não é erro: o Git só pede uma decisão que ele não consegue tomar sozinho."},
  "ENG.06": {"f": "escolha", "p": "O arquivo dados/brutos/respostas.csv tem um erro de digitação. Qual o jeito certo de corrigir?", "o": [["Deixar o bruto intacto e corrigir num script que gera dados/tratados/respostas.csv.", true, "Dado bruto é imutável: a correção fica registrada no código, e qualquer um refaz o caminho."], ["Abrir o CSV bruto na planilha e corrigir à mão.", false, "A correção some do registro: ninguém saberá o que mudou nem por quê."], ["Apagar a linha com erro do arquivo bruto.", false, "Apagar do bruto perde informação sem rastro."]]},
  "ENG.07": {"f": "lacunas", "p": "Complete: validar o dado que chega.", "t": "Antes de calcular, o pipeline confere {{regras}} simples: nota entre 0 e 100, data no formato certo, nenhum id repetido. Se alguma falha, ele {{para}} e registra o motivo no {{log}}, em vez de seguir com dado errado.", "x": ["cores", "continua", "título"], "por": "Confiar que o dado sempre chega certo é o erro mais caro: o número errado vai parar no relatório sem ninguém perceber."},
  "ENG.08": {"f": "escolha", "p": "O pipeline caiu no meio da carga e você roda de novo. O que é um pipeline idempotente?", "o": [["Rodar uma ou várias vezes dá o mesmo resultado: ele não duplica as linhas que já tinham entrado.", true, "Idempotência deixa repetir sem medo, por exemplo apagando a partição do dia antes de carregar de novo, ou usando chave única."], ["Um pipeline que nunca falha.", false, "Todo pipeline pode falhar; idempotente é o que pode ser repetido com segurança."], ["Um pipeline que roda sozinho todo dia.", false, "Isso é agendamento, outra coisa."]]},
  "ENG.09": {"f": "erro", "p": "Uma frase sobre a nuvem está errada. Toque nela.", "t": ["Uma imagem Docker empacota o código e as dependências para rodar igual em qualquer lugar.", "Armazenamento e processamento na nuvem são cobrados pelo uso.", "Uma máquina esquecida ligada no fim de semana não custa nada, porque ninguém está usando.", "Permissões controlam quem pode ler e apagar cada recurso."], "e": 2, "por": "Máquina ligada é cobrada por tempo, usada ou não. Desligue o que não está em uso e acompanhe o custo."},
  "ENG.10": {"f": "escolha", "p": "O que é trabalhar com método ágil?", "o": [["Planejar em ciclos curtos, entregar partes que funcionam e ajustar o plano a cada ciclo.", true, "Ágil tem planejamento, só que frequente e em pedaços pequenos, com retorno de quem usa."], ["Trabalhar sem planejamento, resolvendo o que aparecer.", false, "Scrum e Kanban têm rituais de planejamento; a diferença é o ciclo curto."], ["Entregar tudo de uma vez, no fim do projeto.", false, "Esse é o modelo em cascata; o ágil entrega aos poucos."]]},
  "FMT.01": {"f": "lacunas", "p": "Complete: ler um CSV no padrão brasileiro.", "t": "No arquivo, a linha é Ana;7,5. Para o pandas separar as colunas, informe sep=\"{{;}}\". Para 7,5 virar número, informe decimal=\"{{,}}\". Sem isso, a nota fica como {{texto}} e nenhuma conta funciona.", "x": [".", "|", "número"], "por": "O CSV brasileiro usa ponto e vírgula entre colunas porque a vírgula já é a casa decimal."},
  "FMT.02": {"f": "escolha", "p": "A API devolve cada aluno como {\"nome\": \"Ana\", \"endereco\": {\"cidade\": \"Campo Grande\", \"uf\": \"MS\"}}. O que fazer antes de virar tabela?", "o": [["Achatar a estrutura (por exemplo, com pd.json_normalize), para endereco virar as colunas endereco.cidade e endereco.uf.", true, "A tabela tem uma célula por valor; o objeto aninhado precisa ser aberto em colunas."], ["Nada: o DataFrame guarda o objeto inteiro numa célula e dá para filtrar por cidade normalmente.", false, "Ele até guarda o dicionário numa célula, mas filtrar e agrupar por cidade fica difícil. Achatando, vira coluna comum."], ["Apagar o endereço, porque JSON aninhado não vira tabela.", false, "Vira, sim: basta achatar. Apagar perde informação."]]},
  "FMT.06": {"f": "erro", "p": "A coluna respondida_em mistura 03/04/2026 e 04/03/2026, vindas de sistemas diferentes. Uma frase está errada. Toque nela.", "t": ["No padrão brasileiro, 03/04/2026 é 3 de abril; no americano, 4 de março.", "O ISO 8601 (2026-04-03) não deixa dúvida e ordena certo como texto.", "Basta converter tudo com o mesmo formato: o pandas descobre sozinho qual linha veio de qual sistema.", "O jeito seguro é converter cada origem com o formato dela e só depois juntar."], "e": 2, "por": "Com dia e mês até 12, não há como adivinhar: 03/04 é válido nos dois padrões. É preciso saber a origem de cada linha."},
  "FMT.03": {"f": "ordem", "p": "Você recebeu uma planilha com título na linha 1, cabeçalho em duas linhas e células mescladas. Ponha na ordem a preparação.", "t": ["Abrir a planilha e ver onde os dados começam de verdade", "Ler pulando o título (skiprows) e montar um cabeçalho de uma linha só", "Preencher para baixo os valores das células que estavam mescladas", "Conferir os tipos, principalmente as datas que vieram como número"], "por": "Planilha feita para olhos humanos precisa de limpeza antes de virar tabela: primeiro entender, depois ler, desfazer as mesclas e conferir os tipos."},
  "FMT.05": {"f": "escolha", "p": "Você abriu respostas.parquet no bloco de notas e viu símbolos estranhos. O arquivo está corrompido?", "o": [["Não: Parquet é binário. Abra com pd.read_parquet ou com o DuckDB.", true, "O Parquet guarda por coluna, comprimido e com os tipos; por isso é leve e rápido, mas não é texto."], ["Sim: um arquivo de dados sempre deve abrir como texto.", false, "CSV e JSON são texto; Parquet não, e isso é proposital."], ["Sim: é preciso converter para CSV antes de usar.", false, "Não precisa: o pandas lê Parquet direto, e mais rápido que CSV."]]},
  "FMT.07": {"f": "escolha", "p": "Onde guardar a chave da API que o seu script usa?", "o": [["Numa variável de ambiente ou num arquivo .env que está no .gitignore; o código só lê dali.", true, "A chave fica fora do código e fora do Git. Quem tem o repositório não tem a chave."], ["No próprio script, porque o repositório é só seu.", false, "Repositórios mudam de privado para público, são clonados e compartilhados; chave no código vaza."], ["Num comentário no início do script, para não esquecer.", false, "Comentário também vai para o Git."]]},
  "FMT.09": {"f": "lacunas", "p": "Complete: antes de usar uma base pública.", "t": "Nos microdados do INEP, a coluna TP_SEXO tem 1 e 2. O que cada código significa está no {{dicionário de dados}}. Sem lê-lo, você pode {{interpretar}} o código ao contrário. Ele também diz a {{unidade}} de cada valor e o que significa vazio.", "x": ["título", "somar", "cor"], "por": "O dicionário de dados é o manual da base. Pular essa leitura é o erro mais comum com dados públicos."},
  "FMT.04": {"f": "escolha", "p": "Você quer a tabela de uma página HTML. Qual o caminho certo?", "o": [["Usar um leitor de HTML (pd.read_html ou BeautifulSoup) e selecionar a tabela pelos elementos.", true, "HTML é uma árvore; o leitor entende a estrutura e não quebra se um espaço mudar."], ["Cortar o texto com split nos sinais < e >.", false, "Qualquer atributo novo ou quebra de linha estraga o corte. HTML não é texto plano."], ["Copiar e colar à mão na planilha.", false, "Funciona uma vez, não se repete e erra fácil."]]},
  "FMT.08": {"f": "erro", "p": "Você vai raspar dados de um site público. Uma frase está errada. Toque nela.", "t": ["Antes, leia os termos de uso e o robots.txt.", "Espaçar as requisições (uma pausa entre elas) respeita o servidor.", "Se a página é pública, pode mandar milhares de requisições por segundo.", "Se o site oferece uma API, prefira a API."], "e": 2, "por": "Pública não quer dizer sem limite: requisições em excesso derrubam o servidor e levam ao bloqueio. Raspe devagar e só o necessário."},
  "FMT.10": {"f": "escolha", "p": "Você contou as palavras de mil avaliações de um app e as mais frequentes foram de, a, que, o. O que faltou?", "o": [["Tirar as palavras vazias (stop words), que aparecem em qualquer texto e não dizem nada do assunto.", true, "Sem remover as stop words, a contagem só mostra a gramática. Depois de removê-las, aparecem palavras como lento, trava e entrega."], ["Nada: são as palavras mais importantes das avaliações.", false, "São as mais frequentes em qualquer texto em português; não dizem do que as pessoas reclamam."], ["Contar letras em vez de palavras.", false, "Letras dizem ainda menos sobre o assunto."]]},
  "FMT.11": {"f": "lacunas", "p": "Complete: uma foto como dado.", "t": "Uma foto colorida de 100 por 200 pixels vira uma matriz de {{100}} linhas por 200 colunas para cada canal de cor. Como são {{3}} canais (vermelho, verde e azul), o dado tem formato 100 × 200 × 3: um {{tensor}}.", "x": ["200", "1", "vetor"], "por": "Imagem colorida não é uma tabela simples: tem altura, largura e canais de cor."},
  "FMT.12": {"f": "escolha", "p": "Seu programa precisa enviar dados para o sistema de outra equipe. Qual formato?", "o": [["JSON (ou Parquet, para tabelas grandes): legível por qualquer linguagem e seguro de ler.", true, "Para troca entre sistemas, formatos abertos e com esquema claro. O pickle é só do Python e pode executar código ao ser lido."], ["pickle, porque guarda qualquer objeto Python.", false, "Abrir um pickle de origem desconhecida pode executar código malicioso, e outras linguagens não o leem."], ["Um arquivo .py com os dados dentro de uma variável.", false, "Obriga o outro lado a executar seu código para ler dados: frágil e inseguro."]]},
  "AD.01": {"f": "escolha", "p": "notas é um array do NumPy com 1 milhão de valores. Como somar 5 pontos a todos?", "o": [["notas + 5, que aplica a conta ao array inteiro de uma vez (vetorização).", true, "A operação vetorizada roda em código compilado, dezenas de vezes mais rápida que um laço em Python."], ["for i in range(len(notas)): notas[i] = notas[i] + 5", false, "Funciona, mas o laço em Python sobre um milhão de itens é muito mais lento."], ["notas.append(5)", false, "Arrays do NumPy não têm append, e acrescentar um item não soma nada aos outros."]]},
  "AD.02": {"f": "ordem", "p": "Você acabou de ler respostas.csv com o pandas. Ponha na ordem a primeira inspeção.", "t": ["df.head() para ver as primeiras linhas", "df.info() para ver os tipos e quantos valores não nulos cada coluna tem", "df.isna().sum() para contar os valores ausentes", "df.describe() para ver o resumo das colunas numéricas"], "por": "Antes de analisar, olhe a cara do dado, os tipos e os ausentes. Uma coluna de número lida como texto estraga todas as contas seguintes."},
  "AD.03": {"f": "erro", "p": "Você quer as questões de nível 4 ou 5 da matéria 6. Uma frase está errada. Toque nela.", "t": ["df[(df[\"nivel\"] >= 4) & (df[\"materia_id\"] == 6)] faz o filtro.", "Cada condição vai entre parênteses, porque o & tem precedência alta.", "df[df[\"nivel\"] >= 4 and df[\"materia_id\"] == 6] também funciona, porque and e & são a mesma coisa no pandas.", "Para “ou” no pandas, usa-se |."], "e": 2, "por": "No pandas, and e or não funcionam com colunas inteiras: dão erro de valor ambíguo. Use & e |, com parênteses."},
  "AD.04": {"f": "lacunas", "p": "Complete: o groupby precisa de uma conta.", "t": "respostas.groupby(\"materia\") sozinho só {{separa}} as linhas em grupos; não mostra nenhum número. É preciso dizer a conta: [\"acertou\"].{{mean}}() dá a taxa de acerto, e [\"acertou\"].{{count}}() dá quantas respostas há em cada matéria.", "x": ["soma", "apaga", "max"], "por": "groupby é o “separar”; mean, sum e count são o “calcular”. Sem a conta, não há resultado."},
  "AD.05": {"f": "escolha", "p": "Você juntou respostas (382 linhas) com uma tabela de alunos em que alguns ids aparecem duas vezes, e o resultado teve 410 linhas. O que aconteceu?", "o": [["A chave se repete do lado dos alunos, então cada resposta desses alunos foi duplicada.", true, "Junção com chave repetida dos dois lados multiplica as linhas. Use validate=\"many_to_one\" no merge para o pandas acusar o problema."], ["O merge sempre aumenta o número de linhas.", false, "Com chave única do lado dos alunos, cada resposta casaria com um aluno só, e o total seria 382."], ["O pandas inventou linhas por erro.", false, "Não há invenção: as linhas extras são as cópias das respostas dos alunos duplicados."]]},
  "AD.06": {"f": "escolha", "p": "A tabela tem as colunas aluno, jan, fev, mar (acertos por mês). Qual formato facilita a análise?", "o": [["O formato longo, com as colunas aluno, mes e acertos (pd.melt), uma linha por aluno e mês.", true, "No formato arrumado, cada variável é uma coluna e cada observação é uma linha: um groupby por mês resolve tudo."], ["Manter largo e escrever uma conta para cada mês.", false, "Cada mês novo exige mudar o código; no formato longo, a mesma conta serve para todos."], ["Juntar jan, fev e mar numa coluna só, com o texto “3, 5, 2”.", false, "Vários valores numa célula impedem qualquer conta."]]},
  "AD.07": {"f": "erro", "p": "A coluna acertou tem 20 respostas em branco (NaN). Uma frase está errada. Toque nela.", "t": ["Primeiro vale entender por que estão em branco: o aluno pulou ou o sistema falhou?", "Apagar as linhas pode enviesar a análise, se quem deixa em branco é diferente de quem responde.", "Apagar todas as linhas com NaN é sempre a escolha segura, porque não inventa nada.", "Às vezes o branco é informação: pular a questão pode ser tratado como erro."], "e": 2, "por": "Apagar também muda o resultado: se os brancos se concentram nas questões difíceis, a taxa de acerto sobe artificialmente. A decisão depende do motivo do branco."},
  "AD.08": {"f": "escolha", "p": "Uma carteira subiu 10% em janeiro e 10% em fevereiro. Quanto subiu no bimestre?", "o": [["21%, porque as variações se compõem: 1,10 × 1,10 = 1,21.", true, "Variação percentual se multiplica, não se soma. Em pandas, a variação acumulada sai de (1 + variacao).cumprod() − 1."], ["20%, somando 10% com 10%.", false, "Somar ignora que a segunda alta incide sobre um valor já maior."], ["10%, porque a taxa foi a mesma.", false, "A taxa por mês foi a mesma, mas ela se aplica duas vezes."]]},
  "AD.10": {"f": "lacunas", "p": "Complete: dado maior que a memória.", "t": "Um CSV de 20 GB não cabe na RAM de um notebook comum. Dá para ler em {{partes}} (chunksize) e resumir cada uma, ou consultar o arquivo direto com o {{DuckDB}}. Trocar colunas de texto repetido pelo tipo {{category}} também economiza memória.", "x": ["Excel", "float", "uma vez"], "por": "Carregar tudo de uma vez trava o computador. Ler em partes, usar tipos menores ou um motor que lê do disco resolve."},
  "VIS.01": {"f": "escolha", "p": "Você quer comparar a participação de 8 matérias quase iguais (de 11% a 14%). Qual gráfico deixa ver a diferença?", "o": [["Barras lado a lado, porque o olho compara comprimentos alinhados com precisão.", true, "Posição e comprimento são o que o olho compara melhor; ângulos e áreas, pior."], ["Pizza, porque mostra a participação no todo.", false, "Com 8 fatias parecidas, o olho não distingue 12% de 13% pelo ângulo."], ["Mapa de calor, porque usa cores.", false, "Diferenças pequenas em tons de cor são das mais difíceis de comparar."]]},
  "VIS.02": {"f": "lacunas", "p": "Complete: escolher o gráfico pela pergunta.", "t": "Para ver a taxa de acerto ao longo de 24 meses, use {{linha}}. Para comparar as 6 matérias, use {{barras}}. Para ver se quem estuda mais horas acerta mais, use {{dispersão}}.", "x": ["pizza", "histograma", "mapa"], "por": "Tempo pede linha; comparação de categorias, barras; relação entre duas variáveis numéricas, dispersão."},
  "VIS.03": {"f": "ordem", "p": "Ponha na ordem a montagem de um gráfico de barras com o matplotlib.", "t": ["fig, ax = plt.subplots()", "ax.bar(materias, taxa)", "ax.set_ylabel(\"taxa de acerto\") e ax.set_title(\"Direito Administrativo tem a menor taxa\")", "fig.savefig(\"taxa.png\")"], "por": "Primeiro a figura e os eixos, depois os dados, depois os rótulos e o título, e só então salvar. Rótulos automáticos deixam o leitor adivinhando."},
  "VIS.04": {"f": "erro", "p": "Uma frase sobre o gráfico de barras de 52% e 55% está errada. Toque nela.", "t": ["Com o eixo começando em 0, as barras ficam quase do mesmo tamanho, como os números.", "Com o eixo começando em 50%, a barra de 55% parece 2,5 vezes maior.", "Começar o eixo em 50% é uma boa forma de destacar a diferença, sem enganar ninguém.", "Em barras, o comprimento representa o valor, por isso o eixo começa no zero."], "e": 2, "por": "Em barras, cortar o eixo exagera a diferença: 55% contra 52% é 1,06 vez, não 2,5. Destaque com título e cor, não com eixo truncado."},
  "VIS.05": {"f": "escolha", "p": "Qual título transforma o gráfico de taxa por matéria num gráfico explicativo?", "o": [["“Direito Administrativo tem a menor taxa de acerto: 40%”", true, "O título explicativo diz a conclusão; o leitor confere no gráfico em vez de procurar."], ["“Taxa de acerto por matéria”", false, "Descreve o que está no gráfico, mas deixa a conclusão para o leitor encontrar."], ["“Gráfico 3”", false, "Não diz nada sobre o conteúdo."]]},
  "AD.09": {"f": "ordem", "p": "Ponha na ordem uma análise exploratória com foco.", "t": ["Escrever as perguntas que a análise precisa responder", "Olhar as distribuições das colunas que importam para elas", "Cruzar variáveis e segmentar (por matéria, por nível)", "Anotar hipóteses para testar depois"], "por": "Sem pergunta, viram dezenas de gráficos e nenhuma conclusão. A exploração serve à pergunta e termina em hipóteses."},
  "VIS.06": {"f": "escolha", "p": "No relatório, a amostra foi só de alunos que responderam mais de 30 questões. O que fazer com isso?", "o": [["Escrever na seção de limitações: o resultado vale para alunos frequentes e pode não valer para os outros.", true, "Dizer o limite dá credibilidade e evita que alguém use o número onde ele não vale."], ["Não mencionar, para o resultado parecer mais forte.", false, "Esconder o limite leva a decisões erradas, e quem descobrir depois deixa de confiar no relatório."], ["Refazer a análise com todos os alunos antes de entregar qualquer coisa.", false, "Às vezes não há dados para isso; o essencial é declarar o limite."]]},
  "VIS.07": {"f": "lacunas", "p": "Complete: um painel que ajuda.", "t": "Um bom painel começa por {{poucos}} indicadores, os que respondem às decisões de quem vai usá-lo. Cada número vem com uma {{referência}} (meta ou mês anterior) para dizer se está bom. {{Filtros}} deixam aprofundar sem lotar a tela.", "x": ["todos os", "cor", "Animações"], "por": "Painel com todos os números possíveis faz ninguém saber para onde olhar. Menos indicadores, com contexto, levam a decisões."},
  "MAT.04": {"f": "escolha", "p": "Na tabela de alunos, a linha de Ana é (horas de estudo = 10, acertos = 30). Em ciência de dados, o que é um vetor?", "o": [["Uma lista ordenada de números, como essa linha: cada posição é uma coluna.", true, "A seta da física é um jeito de desenhar um vetor de 2 ou 3 posições; em dados, um vetor pode ter dezenas de posições."], ["Só uma seta com tamanho e direção, como na física.", false, "Isso é uma das leituras. Em dados, a linha da tabela é um vetor, mesmo sem desenho."], ["Um único número, como o total de acertos.", false, "Um número sozinho é um escalar; vetor tem várias posições."]]},
  "MAT.05": {"f": "lacunas", "p": "Complete: o produto de matrizes.", "t": "No produto A × B, cada elemento do resultado é a {{linha}} de A vezes a {{coluna}} de B, somando os produtos. Por isso o número de colunas de A precisa ser {{igual}} ao número de linhas de B.", "x": ["diagonal", "maior", "elemento"], "por": "Multiplicar elemento por elemento é outra operação (produto de Hadamard). O produto de matrizes é linha vezes coluna."},
  "MAT.06": {"f": "erro", "p": "Uma frase sobre sistemas lineares está errada. Toque nela.", "t": ["x + y = 2 e x − y = 0 têm uma solução só: x = 1 e y = 1.", "x + y = 2 e 2x + 2y = 4 têm infinitas soluções, porque a segunda equação é a primeira dobrada.", "x + y = 2 e x + y = 5 têm uma solução, que se acha somando as duas equações.", "O escalonamento mostra qual dos três casos acontece."], "e": 2, "por": "x + y não pode valer 2 e 5 ao mesmo tempo: o sistema não tem solução. Todo sistema linear tem uma, infinitas ou nenhuma solução."},
  "MAT.07": {"f": "escolha", "p": "Por que pôr no modelo o preço em reais e o mesmo preço em centavos é um problema?", "o": [["Uma coluna é combinação linear da outra (centavos = 100 × reais): elas são dependentes e não trazem informação nova.", true, "Colunas linearmente dependentes deixam o modelo sem uma solução única para os coeficientes."], ["Porque centavos ocupam mais memória.", false, "O problema não é memória: é que as duas colunas dizem a mesma coisa."], ["Não é problema: mais colunas sempre melhoram o modelo.", false, "Colunas redundantes atrapalham, principalmente nos modelos lineares."]]},
  "MAT.08": {"f": "lacunas", "p": "Complete: a reta de mínimos quadrados.", "t": "A reta de mínimos quadrados é a que deixa a menor soma dos {{quadrados}} dos resíduos, a distância {{vertical}} de cada ponto até a reta. Ela {{não precisa}} passar por nenhum dos pontos.", "x": ["cubos", "horizontal", "precisa"], "por": "Minimizar a soma dos quadrados é o mesmo critério da regressão linear. A reta acompanha a tendência, não os pontos."},
  "MAT.09": {"f": "ordem", "p": "Ponha na ordem uma análise de componentes principais (PCA) bem feita.", "t": ["Padronizar as colunas (média 0 e desvio 1)", "Calcular as direções de maior variância", "Ver quanto da variância cada componente explica", "Ficar com os primeiros componentes e projetar os dados neles"], "por": "Sem padronizar, a coluna de maior escala (salário em reais contra idade em anos) domina as direções. O PCA gira os eixos para onde os dados mais variam."},
  "MAT.10": {"f": "escolha", "p": "Na descida do gradiente, o erro começou a pular e nunca cai. O que provavelmente aconteceu?", "o": [["A taxa de aprendizado está grande demais: cada passo passa do mínimo para o outro lado.", true, "Com passo menor, o erro desce aos poucos. Passo pequeno demais também atrapalha: fica lento."], ["A taxa está pequena demais.", false, "Passo pequeno deixa a descida lenta, mas não faz o erro pular."], ["O gradiente aponta para o mínimo, então isso não pode acontecer.", false, "O gradiente indica a direção, mas o tamanho do passo decide se você chega lá ou passa direto."]]},
  "ML.01": {"f": "ordem", "p": "Ponha na ordem o começo de um projeto de aprendizado de máquina.", "t": ["Definir o que se quer prever e para que decisão", "Ver quais dados existem e qual coluna é o alvo", "Decidir se é regressão ou classificação", "Só então escolher os algoritmos para testar"], "por": "Escolher o algoritmo antes de definir o alvo e os dados é começar pelo fim. Primeiro a pergunta, depois o dado, depois o tipo do problema."},
  "ML.02": {"f": "erro", "p": "Você quer prever se um aluno vai desistir do curso. Uma das colunas usadas no treino causa vazamento de dados. Toque nela.", "t": ["Número de questões respondidas no primeiro mês.", "Taxa de acerto no primeiro mês.", "Data do cancelamento da matrícula.", "Dias desde o último acesso, medidos no fim do primeiro mês."], "e": 2, "por": "A data do cancelamento só existe depois que o aluno desistiu: no treino, ela entrega a resposta; em uso, ela não existe. É vazamento."},
  "ML.03": {"f": "escolha", "p": "Só 2% das transações são fraude. Um modelo que diz “não é fraude” para todas tem 98% de acurácia. Ele é bom?", "o": [["Não: ele não acha nenhuma fraude (revocação zero). Com classes desbalanceadas, olhe revocação, precisão ou F1.", true, "A acurácia é dominada pela classe grande. A métrica certa depende do custo de cada erro."], ["Sim: 98% de acerto é excelente.", false, "O acerto vem todo da classe comum; o modelo é inútil para o que importa."], ["Sim, desde que o R² também seja alto.", false, "R² é métrica de regressão, não de classificação."]]},
  "ML.04": {"f": "lacunas", "p": "Complete: comparar coeficientes.", "t": "Num modelo com renda em reais e idade em anos, o coeficiente da renda parece minúsculo só porque a renda tem {{escala}} muito maior. Para comparar a força dos atributos, {{padronize}} as colunas antes de treinar. A regularização (Ridge, Lasso) também {{exige}} colunas na mesma escala.", "x": ["unidade de tempo", "apague", "dispensa"], "por": "O coeficiente depende da unidade da coluna. Padronizado, ele passa a ser comparável."},
  "ML.05": {"f": "escolha", "p": "O kNN vai usar renda (em reais) e idade (em anos) para achar os vizinhos. O que fazer antes?", "o": [["Padronizar as duas colunas, para a renda não dominar a distância.", true, "Uma diferença de 1.000 reais pesaria mais que 30 anos de idade. Na mesma escala, as duas contam."], ["Nada: o kNN ajusta as escalas sozinho.", false, "O kNN usa a distância como ela é; não ajusta nada."], ["Acrescentar o máximo de colunas possível.", false, "Com muitas dimensões, tudo fica longe de tudo e os vizinhos perdem sentido."]]},
  "ML.07": {"f": "erro", "p": "Uma frase sobre padronizar os dados está errada. Toque nela.", "t": ["O padronizador aprende a média e o desvio só com os dados de treino.", "Depois, aplica a mesma transformação ao teste, sem reaprender.", "Padronizar todos os dados juntos antes de separar treino e teste é mais preciso e não tem problema.", "Um Pipeline do scikit-learn garante essa ordem dentro da validação cruzada."], "e": 2, "por": "Ajustar com todos os dados deixa a informação do teste vazar para o treino. Primeiro se separa; depois se ajusta só no treino."},
  "ML.06": {"f": "escolha", "p": "Uma árvore de decisão acerta 100% no treino e 70% no teste. O que fazer?", "o": [["Limitar a árvore (profundidade máxima, mínimo de amostras por folha) ou podar, porque ela decorou o treino.", true, "A diferença grande entre treino e teste é sobreajuste. Limitar a árvore ou usar random forest costuma ajudar."], ["Deixar a árvore crescer mais, para acertar também o teste.", false, "Crescer mais aumenta o sobreajuste; ela decora ainda mais o treino."], ["Usar o conjunto de teste no treino, para os dois darem 100%.", false, "Isso destrói a avaliação: não sobra nada para medir o desempenho em dados novos."]]},
  "ML.08": {"f": "lacunas", "p": "Complete: o que os grupos do k-means querem dizer.", "t": "O k-means sempre devolve os {{k}} grupos que você pediu, mesmo que os dados não tenham grupos naturais. Mudando as colunas usadas ou a {{escala}} delas, os grupos mudam. Por isso os grupos são uma {{ferramenta}} para explorar, não uma verdade sobre os alunos.", "x": ["melhores", "ordem", "prova"], "por": "Agrupamento descreve os dados sob uma escolha de colunas e de distância. Mude a escolha, mudam os grupos."},
  "ML.09": {"f": "escolha", "p": "Você testou 200 combinações de hiperparâmetros olhando o resultado no conjunto de teste e relatou a melhor. Qual o problema?", "o": [["O teste virou parte da escolha, e o número relatado fica otimista. A escolha se faz na validação; o teste se usa uma vez, no fim.", true, "Com 200 tentativas, alguma se sai bem por sorte. O teste só mede de forma honesta se não participou da escolha."], ["Nenhum: mais combinações sempre dão um modelo melhor.", false, "Pode até achar um modelo melhor, mas a nota no teste deixa de ser confiável."], ["O problema é só o tempo de computação.", false, "O tempo é o menor dos problemas; a avaliação ficou contaminada."]]},
  "ML.10": {"f": "ordem", "p": "Seu modelo foi para produção. Ponha na ordem o acompanhamento.", "t": ["Registrar as entradas e as previsões do modelo em uso", "Comparar a distribuição das entradas com a do treino", "Medir o desempenho quando os resultados reais chegarem", "Retreinar se o desempenho cair ou os dados mudarem"], "por": "Os dados mudam com o tempo (deriva). Modelo treinado uma vez e esquecido piora em silêncio."},
  "ML.11": {"f": "erro", "p": "Num modelo de desistência, a importância maior foi a da coluna “dias sem acessar”. Uma frase está errada. Toque nela.", "t": ["Essa coluna é a que mais ajuda o modelo a prever.", "Ela pode ser sintoma da desistência, e não a causa.", "Isso prova que fazer o aluno acessar mais todo dia vai impedir a desistência.", "Para falar de causa, seria preciso um experimento."], "e": 2, "por": "Importância de atributo é sobre previsão, não sobre causa. Obrigar o acesso pode não mudar nada se o motivo da desistência for outro."},
  "ML.13": {"f": "escolha", "p": "O seu modelo prevê a demanda de amanhã com erro médio de 120 pedidos. Como saber se ele é bom?", "o": [["Compará-lo com uma previsão ingênua, como repetir o valor de ontem (ou do mesmo dia da semana passada).", true, "Se o ingênuo erra 110, o modelo complicado não está ajudando. A base ingênua é a régua mínima."], ["120 é pouco, então ele é bom.", false, "Sem uma referência, não dá para saber se 120 é pouco."], ["Embaralhar os dias e fazer validação cruzada comum.", false, "Em série temporal, embaralhar usa o futuro para prever o passado; a validação precisa respeitar o tempo."]]},
  "ML.12": {"f": "escolha", "p": "A tabela tem 800 linhas e 12 colunas. Vale começar por uma rede neural?", "o": [["Não: comece por uma regressão ou uma árvore, que costumam ir tão bem quanto ou melhor, e se explicam.", true, "Redes neurais brilham com muito dado e dado não tabular (imagem, texto, som). Em tabela pequena, modelos simples são o ponto de partida."], ["Sim: rede neural é sempre o modelo mais preciso.", false, "Em tabelas pequenas, raramente; e ela é mais difícil de explicar."], ["Sim, porque dispensa preparar os dados.", false, "Redes neurais exigem até mais preparo: escala, codificação, ajuste."]]},
  "NSQ.01": {"f": "lacunas", "p": "Complete: quando o NoSQL faz sentido.", "t": "Um banco NoSQL faz sentido quando o esquema muda muito ou é preciso escalar {{horizontalmente}}, em várias máquinas. Ele não {{substitui}} o relacional em tudo: transações bancárias continuam pedindo garantias {{ACID}}.", "x": ["verticalmente", "apaga", "BASE"], "por": "Cada modelo atende a um tipo de problema. Escolher pelo modismo é que dá errado."},
  "NSQ.02": {"f": "escolha", "p": "No MongoDB, cada pedido embute o nome e o endereço completo do cliente. O cliente muda de endereço. Qual o problema?", "o": [["É preciso atualizar todos os pedidos que embutiram o endereço; referenciar o cliente pelo id evitaria isso.", true, "Embutir é bom para o que se lê junto e não muda; para o que muda, referenciar."], ["Nenhum: o MongoDB atualiza os pedidos sozinho.", false, "Não há essa ligação automática entre documentos."], ["Os pedidos antigos somem.", false, "Eles continuam lá, só que com o endereço antigo."]]},
  "NSQ.03": {"f": "escolha", "p": "Para que um banco colunar, como o DuckDB, é bom?", "o": [["Para consultas de análise que leem poucas colunas de muitas linhas, como a média de acertos por matéria.", true, "Guardar por coluna permite ler só o necessário e comprimir bem. Para muitas gravações pequenas, como cada clique, ele é ruim."], ["Para gravar cada clique de um site, uma linha por vez.", false, "Gravações pequenas e frequentes são o ponto fraco do colunar; ali se usa um banco transacional."], ["Para guardar documentos JSON aninhados.", false, "Isso é o forte dos bancos de documentos."]]},
  "NSQ.04": {"f": "erro", "p": "Uma frase sobre cache com Redis está errada. Toque nela.", "t": ["Guardar o resultado de uma consulta cara evita repeti-la a cada acesso.", "Cada chave pode ter um tempo de expiração.", "Sem expiração, o cache se atualiza sozinho quando o banco muda.", "Redis é bom para contadores, como visitas por página."], "e": 2, "por": "O cache não sabe que o banco mudou: sem expiração (ou sem invalidar a chave), ele continua mostrando o dado velho."},
  "NSQ.05": {"f": "escolha", "p": "Você quer achar “amigos de amigos de amigos” numa rede de milhões de pessoas. Que tipo de banco ajuda?", "o": [["Um banco de grafo, como o Neo4j, feito para percorrer ligações de vários saltos.", true, "No relacional, cada salto é mais uma junção, e a consulta fica lenta. No grafo, seguir a ligação é a operação principal."], ["Um banco relacional, com uma junção por salto.", false, "Funciona para poucos saltos; com muitos e muitos dados, fica lento."], ["Um banco chave-valor.", false, "Ele busca por chave, mas não percorre ligações."]]},
  "NSQ.06": {"f": "escolha", "p": "Sua base tem 200 mil linhas e cabe no notebook. Vale usar Spark?", "o": [["Não: pandas, Polars ou DuckDB resolvem mais rápido e sem complicação.", true, "Spark distribui o trabalho entre várias máquinas; isso só compensa quando o dado não cabe numa máquina."], ["Sim: Spark é sempre mais rápido.", false, "Para dado pequeno, o custo de distribuir deixa o Spark mais lento."], ["Sim, porque big data começa em 100 mil linhas.", false, "Não há esse número: big data é quando volume, velocidade ou variedade passam do que uma máquina dá conta."]]},
  "NSQ.07": {"f": "lacunas", "p": "Complete: lote ou fluxo.", "t": "Se o gestor olha o relatório uma vez por dia, processar em {{lote}}, à noite, basta. Processamento em {{fluxo}} faz sentido quando a decisão é imediata, como bloquear uma fraude no Pix. Montar tempo real sem precisar só aumenta o {{custo}}.", "x": ["tabela", "papel", "lucro"], "por": "A frequência da decisão define a arquitetura. Tempo real sem necessidade é mais caro e mais difícil de manter."},
  "ETI.01": {"f": "escolha", "p": "Como estudar a LGPD para a prova?", "o": [["Pelo texto oficial da lei, artigo por artigo, porque a banca cobra a redação literal.", true, "Resumos de internet trocam palavras e perdem detalhes que a banca explora. A referência é sempre o texto oficial."], ["Por um resumo de internet, porque a lei é longa.", false, "Resumos mudam palavras e omitem incisos; a prova cobra o texto exato."], ["Só pelas notícias sobre multas, porque mostram como a lei funciona.", false, "Notícias mostram casos, mas não o texto que a prova cobra."]]},
  "ETI.02": {"f": "lacunas", "p": "Complete: pseudonimizar não é anonimizar.", "t": "Trocar o nome do aluno por um código é {{pseudonimizar}}: quem tem a tabela de correspondência consegue {{voltar}} ao nome. Mesmo sem ela, cruzar data de nascimento, CEP e curso com outra base pode {{reidentificar}} a pessoa.", "x": ["anonimizar", "apagar", "criptografar"], "por": "Pseudonimizar reduz a exposição, mas o dado continua pessoal. Anonimizar exige que não dê mais para chegar à pessoa."},
  "ETI.03": {"f": "erro", "p": "Uma frase sobre segredos e segurança está errada. Toque nela.", "t": ["Senha guardada no banco deve ser armazenada como hash, não como texto.", "A chave da API fica numa variável de ambiente, fora do código.", "Se o repositório é privado, pôr a senha no código é seguro.", "Criptografia protege a confidencialidade de dados em trânsito e guardados."], "e": 2, "por": "Repositório privado vira público, é clonado e compartilhado; e o histórico guarda a senha mesmo depois de apagada. Segredo nunca vai para o código."},
  "ETI.04": {"f": "escolha", "p": "Um modelo de aprovação de crédito tem 90% de acerto geral, mas 70% num grupo de clientes. O que isso mostra?", "o": [["Que a métrica geral escondia um desempenho pior para um grupo; é preciso avaliar por grupo.", true, "Viés aparece quando se olha por grupo. A média geral pode ser boa e ainda prejudicar um grupo."], ["Nada: o que importa é a métrica geral.", false, "A métrica geral é dominada pelo grupo maior e esconde o prejuízo do menor."], ["Que o grupo tem clientes piores.", false, "A diferença pode vir dos dados de treino ou do rótulo, não das pessoas."]]},
  "ETI.05": {"f": "ordem", "p": "Alguém pergunta de onde veio a taxa de acerto de 49,2% no relatório. Ponha na ordem o caminho para responder.", "t": ["Achar no dicionário de dados a definição do indicador", "Seguir a linhagem: de que tabelas e transformações ele saiu", "Conferir a data da última atualização (atualidade)", "Falar com o dono do dado se houver dúvida"], "por": "Governança é saber o que cada número significa, de onde veio, quando foi atualizado e quem responde por ele."},
  "ETI.06": {"f": "escolha", "p": "Cada vez que você roda a separação de treino e teste, a acurácia muda. Como deixar o resultado reprodutível?", "o": [["Fixar a semente aleatória (random_state=42, por exemplo) e registrar as versões dos dados e do código.", true, "Com a semente fixa, o sorteio se repete igual; com as versões registradas, outra pessoa refaz o mesmo caminho."], ["Rodar várias vezes e relatar a melhor.", false, "Escolher a melhor rodada é otimismo, não reprodutibilidade."], ["Não sortear: usar sempre as primeiras linhas como teste.", false, "Sem sorteio, o teste pode ficar enviesado se os dados tiverem alguma ordem."]]},
};
